// wineLENS wine identity: one resolver for every way a wine arrives (wine list, label scan, manual add).
// Same bottle → same keys → same catalog wine, same place on the globe, same shared notes.
// Deterministic and free: no AI here. Data: shared/catalog-index.json, shared/place-index.json
// (both generated by scripts/build-wine-index.mjs) and the curated shared/region-aliases.json.
const { createHash } = require('node:crypto');
const catalog = require('../shared/catalog-index.json').wines;
const places = require('../shared/place-index.json');
const aliases = require('../shared/region-aliases.json');

const sha = value => createHash('sha256').update(value).digest('hex');
const norm = v => String(v ?? '').normalize('NFKD').replace(/[̀-ͯ]/g, '').toLowerCase().replace(/&/g, ' and ').replace(/[^a-z0-9]+/g, ' ').trim();
// "Valle del Maipo" = "Maipo Valley" = "Maipo"; "Russian River Valley AVA" = "Russian River".
const PREFIX = /^(the|valle del|valle de|vale of|valley of|vallee de la|vallee du|vallee des)\s+/;
const SUFFIX = /\s+(valley|valle|vallee|district|region|ava|aoc|aop|doc|docg|do|doca|igt|igp|wo|gi|qba)$/;
const core = v => { let s = norm(v).replace(PREFIX, ''), prev; do { prev = s; s = s.replace(SUFFIX, ''); } while (s !== prev); return s.trim(); };

// ── Names ────────────────────────────────────────────────────────────
/** "Grand Malbec – Terrazas", or a producer-prefixed name, becomes { title, producer }. */
function splitName(name, producer) {
  let title = String(name || '').trim(), maker = String(producer || '').trim();
  if (!maker) { const at = title.lastIndexOf(' – '); if (at > 0) { maker = title.slice(at + 3).trim(); title = title.slice(0, at).trim(); } }
  const p = norm(maker), t = norm(title);
  if (p && t.startsWith(p + ' ')) { const words = title.split(/\s+/); title = words.slice(maker.split(/\s+/).length).join(' ') || title; }
  return { title, producer: maker };
}
const vintageKey = w => w.vintage ? String(w.vintage) : (w.vintage_state || w.metadata?.vintage_state) === 'non_vintage' ? 'nv' : 'unknown';
/** Producer + wine (no vintage): the catalog identity. Null without a producer (too ambiguous). */
function wineKey(wine) {
  const { title, producer } = splitName(wine.wine_name ?? wine.name, wine.producer);
  const p = norm(producer), t = norm(title);
  return p && t ? sha(`winelens-wine-v1|${p}|${t}`) : null;
}
/** Producer + wine + vintage: the shared-notes identity. */
function bottleKey(wine) {
  const { title, producer } = splitName(wine.wine_name ?? wine.name, wine.producer);
  const p = norm(producer), t = norm(title);
  if (!p || !t) return null;
  const vintage = vintageKey(wine);
  return { key: sha(`winelens-notes-v1|${p}|${t}|${vintage}`), wine: { name: title, producer, vintage } };
}

// ── Countries ────────────────────────────────────────────────────────
const ISO2 = { US: 'USA', FR: 'FRA', IT: 'ITA', ES: 'ESP', PT: 'PRT', DE: 'DEU', AT: 'AUT', NZ: 'NZL', ZA: 'ZAF', LB: 'LBN', AU: 'AUS', AR: 'ARG', CL: 'CHL', GR: 'GRC', CY: 'CYP', MX: 'MEX', HU: 'HUN', GB: 'GBR', UK: 'GBR', CA: 'CAN', UY: 'URY', IL: 'ISR', GE: 'GEO', SI: 'SVN', HR: 'HRV', CH: 'CHE', JP: 'JPN', CN: 'CHN', BR: 'BRA', PE: 'PER', TR: 'TUR', MD: 'MDA', RO: 'ROU', BG: 'BGR', CZ: 'CZE', SK: 'SVK', RS: 'SRB', AM: 'ARM', MA: 'MAR', TN: 'TUN', LU: 'LUX', BE: 'BEL', NL: 'NLD', DK: 'DNK', SE: 'SWE', NO: 'NOR', PL: 'POL', UA: 'UKR', IN: 'IND', MK: 'MKD', ME: 'MNE', BA: 'BIH', AL: 'ALB', MT: 'MLT' };
const COUNTRY_WORDS = { usa: 'USA', 'united states': 'USA', 'united states of america': 'USA', america: 'USA', france: 'FRA', italia: 'ITA', italy: 'ITA', espana: 'ESP', spain: 'ESP', deutschland: 'DEU', germany: 'DEU', osterreich: 'AUT', austria: 'AUT', england: 'GBR', 'united kingdom': 'GBR', britain: 'GBR', 'great britain': 'GBR', wales: 'GBR', scotland: 'GBR', 'new zealand': 'NZL', 'south africa': 'ZAF', mexico: 'MEX', hellas: 'GRC', greece: 'GRC', schweiz: 'CHE', suisse: 'CHE', svizzera: 'CHE', switzerland: 'CHE', magyarorszag: 'HUN', hungary: 'HUN', lebanon: 'LBN', liban: 'LBN', georgia: 'GEO', sakartvelo: 'GEO' };
// "Napa, CA" means California on a wine list, not Canada.
const US_STATES = new Set(['ca','california','or','oregon','wa','washington','ny','new york','va','virginia','tx','texas','mi','michigan','nc','north carolina','pa','pennsylvania','nj','new jersey','az','arizona','nm','new mexico','co','colorado','id','idaho','oh','ohio','mo','missouri','ct','connecticut','ma','massachusetts','md','maryland','ga','georgia usa','vt','vermont','me','maine']);
const countryByCode = new Map(places.countries.map(([code, name]) => [code, name]));
const countryByName = new Map(places.countries.map(([code, name]) => [norm(name), code]));
/** Any spelling of a country (name, native name, ISO2, ISO3) → { code (ISO3), name } or null. */
function resolveCountry(raw) {
  const text = String(raw ?? '').trim(); if (!text) return null;
  if (US_STATES.has(norm(text))) return { code: 'USA', name: countryByCode.get('USA') };
  const upper = text.toUpperCase();
  const code = ISO2[upper] ?? (countryByCode.has(upper) ? upper : null) ?? COUNTRY_WORDS[norm(text)] ?? countryByName.get(norm(text)) ?? null;
  return code && countryByCode.has(code) ? { code, name: countryByCode.get(code) } : null;
}

// ── Places on the globe ──────────────────────────────────────────────
const linkIndex = places.links.map(([region, clusters]) => {
  const [place = '', suffix = ''] = region.split(',').map(s => s.trim());
  return { region, place, country: resolveCountry(suffix)?.code ?? resolveCountry(place)?.code ?? null, clusters, n: norm(place), k: core(place) };
});
const clusterIndex = places.clusters.map(([name, country, id]) => {
  const names = name.split(' / ').map(s => s.trim()).filter(Boolean);
  return { name, country, id, ns: names.map(norm), ks: names.map(core).filter(Boolean) };
});
const aliasIndex = new Map(aliases.aliases.map(([alias, country, target]) => [norm(alias), { country, target }]));
/**
 * Free text ("Maipo Valley", "Napa, CA", "Bourgogne") + country → where it sits on the globe.
 * status: mapped (catalog region or winery cluster with geometry) · unmapped (a known catalog region
 * with no clusters yet) · country (country only) · unknown (needs mapping; never guessed).
 */
function resolvePlace(regionText, countryText) {
  // "Napa Valley, US" and "Mendoza (Argentina)" both carry their country.
  const text = String(regionText ?? '').replace(/^(.*?)\s*\(([^)]*)\)\s*$/, '$1, $2');
  const [placeText = '', suffix = ''] = text.split(',').map(s => s.trim());
  // A country written with the place ("Mendoza, Argentina") is more specific than a separate country field.
  let country = resolveCountry(suffix) ?? resolveCountry(countryText);
  const original = String(regionText ?? '').trim();
  if (!placeText) return { status: country ? 'country' : 'unknown', region: '', country, original };
  if (resolveCountry(placeText) && !suffix) { country ??= resolveCountry(placeText); return { status: 'country', region: '', country, original }; }
  const n = norm(placeText), k = core(placeText);
  const fits = x => !country || !x.country || x.country === country.code;
  const named = code => code ? { code, name: countryByCode.get(code) } : null;
  // 1. Catalog regions, 2. curated aliases, 3. winerymap clusters (own name, alternate names, then core).
  let link = linkIndex.find(l => l.n === n && fits(l)) ?? linkIndex.find(l => k && l.k === k && fits(l));
  let clusterName = null;
  if (!link) {
    const alias = aliasIndex.get(n) ?? aliasIndex.get(k);
    if (alias && fits(alias)) {
      if (alias.target.startsWith('cluster:')) clusterName = alias.target.slice(8);
      else link = linkIndex.find(l => l.region === alias.target) ?? null;
      country ??= named(alias.country);
    }
  }
  if (link) {
    country ??= named(link.country);
    return { status: link.clusters.length ? 'mapped' : 'unmapped', region: link.region, country, link: link.region, original };
  }
  let hits = clusterName ? clusterIndex.filter(c => c.name === clusterName) : clusterIndex.filter(c => fits(c) && c.ns.includes(n));
  if (!hits.length && k) hits = clusterIndex.filter(c => fits(c) && c.ks.includes(k));
  if (hits.length && (country || new Set(hits.map(c => c.country)).size === 1)) {
    const hit = hits[0];
    return { status: 'mapped', region: hit.name, country: country ?? named(hit.country), cluster: hit.id, original };
  }
  return { status: 'unknown', region: placeText, country, original };
}

// ── Catalog wines ────────────────────────────────────────────────────
function bigrams(text) {
  const s = text.replace(/ /g, ''), grams = new Map();
  for (let i = 0; i < s.length - 1; i++) { const g = s.slice(i, i + 2); grams.set(g, (grams.get(g) || 0) + 1); }
  return grams;
}
function dice(a, b) {
  let overlap = 0, total = 0;
  for (const [g, c] of a) { total += c; overlap += Math.min(c, b.get(g) || 0); }
  for (const c of b.values()) total += c;
  return total ? 2 * overlap / total : 0;
}
const catalogIndex = catalog.map(w => ({ w, key: wineKey({ wine_name: w.title, producer: w.producer }), producer: bigrams(norm(w.producer)), all: bigrams(norm(`${w.producer} ${w.title}`)) }));
/** Exact identity first; otherwise a close spelling of the same producer + wine. Never a different wine. */
function matchCatalog(wine) {
  const key = wineKey(wine);
  const exact = key && catalogIndex.find(c => c.key === key);
  if (exact) return { id: exact.w.id, kind: 'exact', score: 1 };
  const { title, producer } = splitName(wine.wine_name ?? wine.name, wine.producer);
  if (!norm(title)) return null;
  const all = bigrams(norm(`${producer} ${title}`)), maker = bigrams(norm(producer));
  let best = null;
  for (const c of catalogIndex) {
    const score = dice(all, c.all), makerScore = producer ? dice(maker, c.producer) : 0;
    if (producer && makerScore < 0.75) continue;
    if (!best || score > best.score) best = { id: c.w.id, score };
  }
  if (!best || best.score < 0.78) return null;
  return { id: best.id, kind: best.score >= 0.9 && producer ? 'match' : 'possible', score: Math.round(best.score * 100) / 100 };
}
const catalogById = new Map(catalog.map(w => [w.id, w]));
// Single-column lists write "Terrazas de los Andes Grand Malbec": peel a known producer off either end.
const knownProducers = [...new Set(catalog.map(w => w.producer).filter(Boolean))].map(p => ({ p, n: norm(p) })).sort((a, b) => b.n.length - a.n.length);
function splitKnownProducer(name) {
  const t = norm(name), words = String(name || '').trim().split(/\s+/);
  for (const { p, n } of knownProducers) {
    const size = p.split(/\s+/).length;
    if (t.startsWith(n + ' ') && words.length > size) return { title: words.slice(size).join(' '), producer: p };
    if (t.endsWith(' ' + n) && words.length > size) return { title: words.slice(0, -size).join(' ').replace(/[\s,–-]+$/, ''), producer: p };
  }
  return null;
}

// ── One entry, fully resolved ────────────────────────────────────────
const COLORS = { red: 'Red', white: 'White', sparkling: 'Sparkling', rose: 'Rose', rosé: 'Rose', orange: 'Orange', dessert: 'Dessert', fortified: 'Dessert', sweet: 'Dessert' };
function resolveEntry(raw) {
  let { title, producer } = splitName(raw.wine_name, raw.producer);
  // Only keep a peeled producer when it lands on that producer's catalog wine ("Storm Point Shiraz" stays as written).
  const peeled = !producer && splitKnownProducer(title), peeledMatch = peeled && matchCatalog({ wine_name: peeled.title, producer: peeled.producer });
  if (peeledMatch && peeledMatch.kind !== 'possible') ({ title, producer } = peeled);
  const vintage = Number.isInteger(raw.vintage) ? raw.vintage : null;
  const vintage_state = vintage ? 'year' : raw.vintage === 'NV' || raw.vintage === 'non-vintage' ? 'non_vintage' : 'unknown';
  const match = matchCatalog({ wine_name: title, producer });
  const twin = match && match.kind !== 'possible' ? catalogById.get(match.id) : null;
  const place = resolvePlace(raw.region || twin?.region || '', raw.country || twin?.country || '');
  const color = COLORS[norm(raw.color)] ?? (twin ? twin.type : 'Unknown');
  const identity = { wine_name: twin?.title ?? title, producer: twin?.producer ?? producer, vintage, vintage_state };
  return {
    ...identity,
    region: place.region || '', country: place.country?.name || String(raw.country || '').trim(), grape: String(raw.grape || twin?.grape || '').trim(), color,
    price: String(raw.price || '').trim().slice(0, 40), source_line: String(raw.source_line || '').trim().slice(0, 200),
    confidence: Number.isFinite(raw.confidence) ? Math.max(0, Math.min(1, raw.confidence)) : 0.5,
    catalog: match ? { id: match.id, kind: match.kind, score: match.score, title: catalogById.get(match.id)?.title, producer: catalogById.get(match.id)?.producer } : null,
    place: { status: place.status, region: place.region, country: place.country?.code ?? null, original: place.original },
    keys: { wine: wineKey(identity), bottle: bottleKey(identity)?.key ?? null },
  };
}
module.exports = { norm, core, splitName, wineKey, bottleKey, resolveCountry, resolvePlace, matchCatalog, resolveEntry, catalogById, sha };
